  ('ramayana-popular-sulochana-meghnad-v1', 'war_performance', 1, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_LATER_DEVOTIONAL_DB_V1","expectationId":"popular-sulochana-meghnad","storyId":"ramayana-popular-sulochana-meghnad-v1","sourceFamily":"later_marathi_performance_reception","sourceRefs":["valmiki-yuddha-90-indrajit-death","ucsd-sulochana-performance-history","sagar-ramayan-series"],"selectedExpressionRelation":"The selected expression ends Indrajit''s battle but does not contain the flying arm, written message, smiling head, or Sulochana''s retrieval journey.","alignmentNote":"The arm-and-head sequence follows documented later performance history. Its sati ending is disclosed critically rather than retold as a devotional ideal."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["sulochana","indrajit","lakshmana","ravana","rama","vanara-guards"],"places":["lanka-battlefield","lanka-palace","rama-war-camp"],"relationships":[{"target_kind":"story_cycle","target_id":"indrajits-last-war","relationship":"later_performance_follows","inverse_relationship":"has_later_performance_afterlife","bidirectional":true},{"target_kind":"entity","target_id":"sulochana","relationship":"centres_grief_and_agency_of","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"entity","target_id":"indrajit","relationship":"responds_to_death_of","inverse_relationship":"death_is_received_in","bidirectional":true}],"expressionScope":"Later Marathi performance and wider popular reception placed after Indrajit''s death, not inside the selected epic expression."}'::jsonb),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'war_regional', 2, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_LATER_DEVOTIONAL_DB_V1","expectationId":"regional-ahiravana-mahiravana-rescue","storyId":"ramayana-regional-ahiravana-mahiravana-rescue-v1","sourceFamily":"later_regional_ahiravana_mahiravana_families","sourceRefs":["sohini-pillai-ahiravana-scholarship","sathya-sai-nether-region","sagar-ramayan-series"],"selectedExpressionRelation":"This subterranean abduction and rescue is absent from the selected expression and is placed beside the late Lanka war rather than inserted into it.","alignmentNote":"Shared episodes are followed by two explicitly labelled branches. Ahiravana and Mahiravana are not silently treated as one stable character."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["hanuman","rama","lakshmana","mahiravana","ahiravana","makaradhwaja","vibhishana"],"places":["lanka-war-camp","patala-gateway","patala-sanctum"],"relationships":[{"target_kind":"story_cycle","target_id":"indrajits-last-war","relationship":"regional_war_interlude_near","inverse_relationship":"has_regional_interlude","bidirectional":true},{"target_kind":"story_cycle","target_id":"ravanas-final-battle","relationship":"regional_war_interlude_before","inverse_relationship":"has_regional_preceding_interlude","bidirectional":true},{"target_kind":"entity","target_id":"hanuman","relationship":"centres_rescue_by","inverse_relationship":"rescues_in","bidirectional":true},{"target_kind":"entity","target_id":"makaradhwaja","relationship":"introduces_later_son_tradition_of","inverse_relationship":"appears_in","bidirectional":true}],"expressionScope":"A variant-aware later regional story map: an eastern Mahiravana family and a popular Panchamukhi Ahiravana/Mahiravana family share a rescue scaffold but retain different names and mechanics."}'::jsonb),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'aftermath_reception', 3, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_LATER_DEVOTIONAL_DB_V1","expectationId":"popular-luv-kush-ashvamedha-confrontation","storyId":"ramayana-popular-lava-kusha-ashvamedha-v1","sourceFamily":"modern_institutional_popular_lava_kusha_retelling","sourceRefs":["ttd-lava-kusha-ashvamedha-brief","ramayana-dutt-selected-inventory","sagar-ramayan-series"],"selectedExpressionRelation":"The selected expression has the Ashvamedha and the twins singing Rama''s story but not this full escalating horse-battle sequence.","alignmentNote":"The TTD brief supplies the named confrontation order and ending. Devam adds no television dialogue or unsupported combat choreography."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["lava","kusha","sita","valmiki","rama","shatrughna","bharata","lakshmana","hanuman"],"places":["valmiki-ashram","ashvamedha-horse-route","forest-battlefield","ayodhya"],"relationships":[{"target_kind":"story_cycle","target_id":"kingdom-tales-and-twins","relationship":"popularly_expands_after","inverse_relationship":"has_popular_battle_expansion","bidirectional":true},{"target_kind":"story_cycle","target_id":"twins-sing-sita-returns","relationship":"popularly_reframes_recognition_in","inverse_relationship":"has_popular_recognition_variant","bidirectional":true},{"target_kind":"entity","target_id":"lava","relationship":"centres_choice_of","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"entity","target_id":"kusha","relationship":"centres_choice_of","inverse_relationship":"appears_in","bidirectional":true}],"expressionScope":"Tirumala Tirupati Devasthanams'' expressly brief popular Lava-Kusha battle account expanded into a coherent consumer sequence, separate from the selected Dutt sacrifice-and-recitation sequence."}'::jsonb),
  ('ramayana-popular-hanuman-opens-chest-v1', 'devotional_afterlife', 4, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_LATER_DEVOTIONAL_DB_V1","expectationId":"popular-hanuman-opens-chest","storyId":"ramayana-popular-hanuman-opens-chest-v1","sourceFamily":"modern_popular_hanuman_devotional_tale","sourceRefs":["lutgendorf-hanuman-tale","ramayana-dutt-selected-inventory","sagar-ramayan-series"],"selectedExpressionRelation":"The selected expression includes Sita giving Hanuman a necklace but not the pearl-breaking test or opening of the chest.","alignmentNote":"The complete popular devotional sequence follows scholarly reception documentation without copying its prose or attributing the tale to Valmiki."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["hanuman","rama","sita","ayodhya-court"],"places":["ayodhya-coronation-hall"],"relationships":[{"target_kind":"story_cycle","target_id":"companions-depart","relationship":"devotional_afterlife_follows","inverse_relationship":"has_devotional_afterlife","bidirectional":true},{"target_kind":"entity","target_id":"hanuman","relationship":"reveals_devotion_of","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"devotional_text","target_id":"hanuman-chalisa","relationship":"shares_rama_bhakti_world_with","inverse_relationship":"connects_to_story","bidirectional":true}],"expressionScope":"Modern popular devotional necklace-and-heart story documented in reception history and devotional art, not a Valmiki or selected-Dutt episode."}'::jsonb),
  ('ramayana-popular-hanuman-sindoor-v1', 'devotional_afterlife', 5, 2, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_LATER_DEVOTIONAL_DB_V1","expectationId":"popular-hanuman-sindoor","storyId":"ramayana-popular-hanuman-sindoor-v1","sourceFamily":"modern_popular_hanuman_sindoor_tale","sourceRefs":["lutgendorf-hanuman-tale"],"selectedExpressionRelation":"The tale has no known premodern textual source in the scholarly reception study and is not part of the selected expression.","alignmentNote":"The narration preserves the familiar story while marking its modern explanatory character. Appended weekday and wish-fulfilment promises are disclosed as variant phalashruti, not guaranteed guidance."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["hanuman","rama","sita","ayodhya-court"],"places":["ayodhya-palace","ayodhya-court"],"relationships":[{"target_kind":"story_cycle","target_id":"companions-depart","relationship":"devotional_afterlife_follows","inverse_relationship":"has_devotional_afterlife","bidirectional":true},{"target_kind":"story","target_id":"ramayana-popular-hanuman-opens-chest-v1","relationship":"shares_modern_devotional_family_with","inverse_relationship":"shares_modern_devotional_family_with","bidirectional":true},{"target_kind":"living_practice","target_id":"hanuman-sindoor-offering-variants","relationship":"later_explains","inverse_relationship":"has_popular_explanatory_story","bidirectional":true}],"expressionScope":"Modern popular devotional explanation for Hanuman''s sindoor association, with living practice kept separate from the story''s promised fruits and from universal ritual instruction."}'::jsonb)
) as source(slug, arc_slug, backbone_ordinal, turn_ordinal, source_range, visual_direction)
