join public.narrative_series series on series.slug='ramayana-expected-stories-later-devotional-v1'
join public.narrative_moments moment on moment.series_id=series.id and moment.slug=source.moment_slug
on conflict (moment_id, slug) do update set beat_ordinal=excluded.beat_ordinal, source_range=excluded.source_range,
  visual_direction=excluded.visual_direction, rights_lane=excluded.rights_lane, publication_state=excluded.publication_state, updated_at=now();

insert into public.narrative_beat_texts (beat_id, language_code, title, narration, text_status, rights_lane, publication_state)
select beat.id, source.language_code, source.title, source.narration, 'source_aligned', 'derivative_allowed', 'draft'
from (values
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-meghnad-falls-in-battle', 'en', 'Lakshmana defeats Indrajit', 'In the war outside Lanka, Lakshmana finally kills Ravana''s son Indrajit, also remembered as Meghnad. That death belongs to the epic battle sequence. The later Sulochana story begins only after this shared event and asks what the news means inside the household he has left behind.'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-meghnad-falls-in-battle', 'hi', 'लक्ष्मण इंद्रजित को पराजित करते हैं', 'लंका के बाहर युद्ध में लक्ष्मण अंततः रावण के पुत्र इंद्रजित, जिन्हें मेघनाद भी कहा जाता है, का वध करते हैं। यह मृत्यु महाकाव्य के युद्ध-क्रम का भाग है। बाद की सुलोचना-कथा इसी साझा घटना के बाद आरम्भ होकर पूछती है कि यह समाचार पीछे छूटे परिवार तक कैसे पहुँचता है।'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-arm-enters-palace', 'en', 'A severed arm carries the news', 'In the documented stage telling, an arm severed in battle flies into Sulochana''s chamber. The impossible arrival turns distant warfare into immediate personal loss. She does not yet have a messenger she can question, only a fragment of the person whose fate she must understand.'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-arm-enters-palace', 'hi', 'कटा हुआ हाथ समाचार लेकर आता है', 'दर्ज रंगमंचीय कथा में युद्ध में कटा हुआ हाथ उड़कर सुलोचना के कक्ष में पहुँचता है। यह असम्भव आगमन दूर चल रहे युद्ध को तत्काल निजी क्षति में बदल देता है। उनके सामने कोई ऐसा दूत नहीं है जिससे वे प्रश्न कर सकें; केवल उस व्यक्ति का अंग है जिसकी नियति उन्हें समझनी है।'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-arm-writes-message', 'en', 'The arm writes what happened', 'The arm writes that Meghnad has been killed. Sulochana''s uncertainty becomes grief, but the stage image also gives her knowledge that the palace might otherwise conceal or delay. The device belongs to this performance lineage; Devam does not present it as a scene found in every Ramayana.'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-arm-writes-message', 'hi', 'हाथ लिखकर घटना बताता है', 'वह हाथ लिखकर बताता है कि मेघनाद मारे गए हैं। सुलोचना की आशंका शोक में बदल जाती है, पर यह रंगमंचीय दृश्य उन्हें वह जानकारी भी देता है जिसे राजमहल छिपा या देर से पहुँचा सकता था। यह युक्ति इसी प्रदर्शन-परंपरा की है; देवम् इसे हर रामायण में उपस्थित घटना नहीं बताता।'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-asks-ravana-for-leave', 'en', 'Sulochana decides to recover Meghnad''s head', 'The later play says that Meghnad''s head is in Rama''s camp. Sulochana asks Ravana for permission to cross the enemy line and recover it. Her journey moves her out of the protected palace and into a field shaped by decisions made by Ravana, Meghnad, and the armies, yet she must bear the consequence herself.'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-asks-ravana-for-leave', 'hi', 'सुलोचना मेघनाद का सिर वापस लाने का निश्चय करती हैं', 'बाद का नाटक बताता है कि मेघनाद का सिर राम के शिविर में है। सुलोचना रावण से शत्रु-पंक्ति पार कर उसे वापस लाने की अनुमति माँगती हैं। उनकी यात्रा उन्हें सुरक्षित राजमहल से उस रणभूमि में ले जाती है जिसे रावण, मेघनाद और सेनाओं के निर्णयों ने बनाया, पर परिणाम उन्हें स्वयं उठाना पड़ता है।'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-enters-rama-camp', 'en', 'She asks Rama''s camp for the head', 'Sulochana reaches the opposing camp and states why she has come. The request changes the scene from combat to the handling of a dead opponent and a grieving relative. Rama''s side must decide whether victory will include humiliation or whether the remains can be returned with dignity.'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-enters-rama-camp', 'hi', 'वे राम के शिविर से सिर माँगती हैं', 'सुलोचना विरोधी शिविर में पहुँचकर अपने आने का कारण बताती हैं। यह अनुरोध दृश्य को युद्ध से हटाकर मृत प्रतिद्वंद्वी और शोकग्रस्त परिजन के साथ व्यवहार की ओर ले जाता है। राम के पक्ष को तय करना है कि विजय अपमान तक जाएगी या अवशेष सम्मानपूर्वक लौटाए जाएँगे।'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-head-smiles-in-test', 'en', 'The performance gives the dead head a final sign', 'In this stage version, members of the camp ask Sulochana to make the head smile before they return it. The head smiles, confirming the bond as the play imagines it, and is restored to her. This supernatural test is a feature of the documented performance, not a measure by which any real person''s grief or fidelity should be judged.'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-head-smiles-in-test', 'hi', 'प्रदर्शन मृत सिर से अंतिम संकेत दिलाता है', 'इस रंगमंचीय रूप में शिविर के लोग सिर लौटाने से पहले सुलोचना से उसे मुस्कराने को कहते हैं। नाटक की कल्पना में सिर मुस्कराकर संबंध की पहचान देता है और उन्हें लौटा दिया जाता है। यह अलौकिक परीक्षा दर्ज प्रदर्शन की विशेषता है, किसी वास्तविक व्यक्ति के शोक या निष्ठा को परखने का मानदंड नहीं।'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-performance-ending-bounded', 'en', 'The old stage ending requires a clear boundary', 'The historical stage account continues toward Sulochana entering Meghnad''s funeral pyre. Devam records that ending because hiding it would falsify the lineage, but does not dramatize it as fulfilment, purity, or devotion. Sati was a lethal social practice: the consumer journey closes on her receipt of the remains, her grief, and the obligation to remember the ending critically.'),
  ('ramayana-popular-sulochana-meghnad-v1', 'sulochana-performance-ending-bounded', 'hi', 'पुराने रंगमंचीय अंत को स्पष्ट सीमा के साथ समझना आवश्यक है', 'ऐतिहासिक रंगमंचीय विवरण आगे सुलोचना के मेघनाद की चिता में प्रवेश तक जाता है। देवम् उस अंत को छिपाता नहीं, क्योंकि ऐसा करना परंपरा को गलत बनाता, पर उसे पूर्णता, पवित्रता या भक्ति के रूप में नाटकीय भी नहीं बनाता। सती एक घातक सामाजिक प्रथा थी; उपभोक्ता-यात्रा अवशेष मिलने, उनके शोक और उस अंत को आलोचनात्मक स्मृति में रखने की जिम्मेदारी पर समाप्त होती है।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-war-seeks-hidden-ally', 'en', 'The later tale opens a road beneath the war', 'As Ravana''s position worsens, later Ramayana traditions bring in a subterranean ally called Mahiravana, Ahiravana, or sometimes both. His relationship to Ravana also changes across tellings. What remains stable is the new danger: Rama and Lakshmana can be removed from the battlefield without being defeated in open combat.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-war-seeks-hidden-ally', 'hi', 'बाद की कथा युद्ध के नीचे एक नया मार्ग खोलती है', 'रावण की स्थिति बिगड़ने पर बाद की रामायण-परंपराएँ महीरावण, अहिरावण अथवा कभी दोनों नामों वाले पाताल-स्थित सहयोगी को लाती हैं। रावण से उसका संबंध भी कथाओं में बदलता है। स्थिर तत्व नया संकट है: राम और लक्ष्मण को खुले युद्ध में हराए बिना रणभूमि से हटाया जा सकता है।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-hanuman-guards-camp', 'en', 'Hanuman turns himself into the camp''s guard', 'Vibhishana warns that deception, not a frontal attack, is likely. Hanuman surrounds or guards the sleeping camp, determined that no stranger will reach the brothers. The defence is powerful against force, but it depends on recognizing whom to trust.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-hanuman-guards-camp', 'hi', 'हनुमान स्वयं शिविर के प्रहरी बनते हैं', 'विभीषण चेताते हैं कि सामने से आक्रमण नहीं, छल होने की आशंका है। हनुमान सोते हुए शिविर को घेरकर अथवा उसके द्वार पर खड़े होकर निश्चय करते हैं कि कोई अपरिचित राम-लक्ष्मण तक नहीं पहुँचेगा। यह रक्षा बल के विरुद्ध शक्तिशाली है, पर इसकी सफलता इस पर निर्भर है कि विश्वसनीय रूप को पहचाना जा सके।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-trusted-disguise-opens-way', 'en', 'A trusted appearance defeats the outer guard', 'The abductor enters through disguise, illusion, or a form the guards believe they know. Versions disagree about the exact disguise, so Devam does not choose one as universal. The important turn is that trust is imitated successfully and the brothers are taken before the camp understands what has happened.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-trusted-disguise-opens-way', 'hi', 'विश्वसनीय रूप बाहरी पहरे को पार कर जाता है', 'अपहरणकर्ता वेश, माया अथवा ऐसे रूप से भीतर आता है जिसे प्रहरी परिचित मान लेते हैं। कथाएँ सटीक वेश पर सहमत नहीं, इसलिए देवम् किसी एक को सार्वभौमिक नहीं बनाता। निर्णायक मोड़ यह है कि विश्वास की सफल नकल होती है और शिविर को घटना समझ आने से पहले दोनों भाई उठा लिए जाते हैं।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-brothers-taken-to-patala', 'en', 'Rama and Lakshmana disappear into Patala', 'Rama and Lakshmana are carried into an underworld kingdom where the captor intends a sacrificial killing. The deity, rite, and kinship details differ materially among branches. The shared story pressure is immediate: the battlefield army has lost both leaders, and rescue requires finding a route into a world outside its map.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-brothers-taken-to-patala', 'hi', 'राम और लक्ष्मण पाताल ले जाए जाते हैं', 'राम और लक्ष्मण को पाताल के राज्य में ले जाया जाता है, जहाँ अपहरणकर्ता बलि द्वारा उनकी हत्या करना चाहता है। देवता, अनुष्ठान और पारिवारिक संबंधों का विवरण शाखाओं में बहुत बदलता है। साझा संकट तत्काल है: रणभूमि की सेना ने दोनों नेताओं को खो दिया है और बचाव के लिए अपने मानचित्र से बाहर की दुनिया का मार्ग खोजना होगा।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-hanuman-descends', 'en', 'Hanuman follows the hidden passage downward', 'When the loss is discovered, Hanuman takes responsibility for pursuit rather than surrendering to shame over the failed guard. Clues lead him down toward Patala. The rescue changes from battlefield strength to navigation, recognition, restraint, and speed before the threatened sacrifice can occur.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-hanuman-descends', 'hi', 'हनुमान गुप्त मार्ग से नीचे उतरते हैं', 'अपहरण का पता लगने पर हनुमान असफल पहरे की लज्जा में रुकने के बजाय पीछा करने की जिम्मेदारी लेते हैं। संकेत उन्हें पाताल की ओर नीचे ले जाते हैं। अब बचाव रणभूमि के बल से बदलकर मार्ग-खोज, पहचान, संयम और प्रस्तावित बलि से पहले की गति का काम बन जाता है।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-makaradhwaja-at-gate', 'en', 'Makaradhwaja guards the gate', 'At the entrance Hanuman meets Makaradhwaja, a formidable guard who identifies himself in this later tradition as Hanuman''s son. Popular versions explain the birth through a drop from Hanuman entering a fish, but details vary. Hanuman is surprised, yet the immediate conflict is duty: the guard will not abandon his post and the rescuer cannot turn back.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-makaradhwaja-at-gate', 'hi', 'मकरध्वज द्वार की रक्षा करता है', 'प्रवेश-द्वार पर हनुमान की भेंट शक्तिशाली प्रहरी मकरध्वज से होती है, जो इस बाद की परंपरा में स्वयं को हनुमान का पुत्र बताता है। लोकप्रिय रूप उसके जन्म को हनुमान से निकली एक बूँद के मछली तक पहुँचने से जोड़ते हैं, पर विवरण बदलते हैं। हनुमान चकित हैं, फिर भी तत्काल टकराव कर्तव्य का है: प्रहरी पद नहीं छोड़ेगा और रक्षक लौट नहीं सकता।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-father-son-contest', 'en', 'The unexpected father and son fight without hatred', 'Hanuman and Makaradhwaja test one another in combat because their duties point in opposite directions. Hanuman overcomes and restrains him rather than treating the newly discovered relationship as permission to demand obedience. The gate opens, but Makaradhwaja''s loyalty remains part of his character rather than a defect erased by defeat.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-father-son-contest', 'hi', 'अप्रत्याशित पिता-पुत्र बिना वैर के लड़ते हैं', 'हनुमान और मकरध्वज युद्ध में एक-दूसरे की परीक्षा लेते हैं, क्योंकि उनके कर्तव्य विपरीत दिशाओं में हैं। हनुमान उसे पराजित कर बाँधते हैं, पर नए मिले संबंध को आज्ञाकारिता माँगने का अधिकार नहीं बनाते। द्वार खुलता है, किन्तु मकरध्वज की निष्ठा उसकी चरित्र-विशेषता बनी रहती है, हार से मिटा दोष नहीं।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-eastern-mahiravana-branch', 'en', 'Branch A: Mahiravana''s nether kingdom', 'In one eastern and modern devotional family, Mahiravana is the principal ruler whom Hanuman must outwit and defeat inside Patala. Some related tellings add Ahiravana as another figure or a later combatant; others do not. This branch therefore keeps Mahiravana''s name and sequence without importing the five-lamp mechanism from a different popular family.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-eastern-mahiravana-branch', 'hi', 'शाखा क: महीरावण का पाताल-राज्य', 'एक पूर्वी और आधुनिक भक्तिपरक कथा-परिवार में महीरावण पाताल का मुख्य शासक है, जिसे हनुमान को छल समझकर पराजित करना है। कुछ संबंधित कथाएँ अहिरावण को अलग या बाद के योद्धा के रूप में जोड़ती हैं, कुछ नहीं। इसलिए यह शाखा महीरावण का नाम और क्रम सुरक्षित रखती है, दूसरी लोकप्रिय शाखा के पाँच दीपक इसमें नहीं मिलाती।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-panchamukhi-five-lamp-branch', 'en', 'Branch B: five lamps and Panchamukhi Hanuman', 'A widely familiar popular branch says the captor''s life is protected by five lamps burning in different directions. Hanuman assumes a five-faced form so the flames can be extinguished together, then defeats the captor. This Panchamukhi solution is told as its own reception branch; it is not backfilled into every Mahiravana or Ahiravana text.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-panchamukhi-five-lamp-branch', 'hi', 'शाखा ख: पाँच दीपक और पंचमुखी हनुमान', 'बहुत परिचित लोकप्रिय शाखा कहती है कि अपहरणकर्ता का जीवन अलग दिशाओं में जलते पाँच दीपकों से सुरक्षित है। हनुमान पंचमुखी रूप धारण कर सभी लौ एक साथ बुझाते हैं और फिर शत्रु को पराजित करते हैं। यह पंचमुखी समाधान अपनी अलग लोक-स्वीकृति शाखा है; इसे हर महीरावण या अहिरावण पाठ में पीछे से नहीं जोड़ा जाता।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-sacrifice-stopped', 'en', 'The threatened sacrifice is stopped', 'Whichever branch a listener follows, Hanuman reaches Rama and Lakshmana before the planned killing is completed. He breaks the captor''s control and frees them. Devam leaves the ritual''s named recipient and exact method inside its branch because combining them would invent a false agreement among traditions.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-sacrifice-stopped', 'hi', 'प्रस्तावित बलि रोक दी जाती है', 'श्रोता जिस भी शाखा का अनुसरण करे, हनुमान प्रस्तावित हत्या पूरी होने से पहले राम और लक्ष्मण तक पहुँचते हैं। वे अपहरणकर्ता का नियंत्रण तोड़कर दोनों को मुक्त करते हैं। देवम् अनुष्ठान के नामित देवता और सटीक विधि को उसी शाखा में रखता है, क्योंकि उन्हें जोड़ना परंपराओं के बीच झूठी सहमति गढ़ना होगा।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-makaradhwaja-after-rescue', 'en', 'Some tellings leave Makaradhwaja with a kingdom', 'In a common later resolution, Makaradhwaja is released and entrusted with responsibility for the nether kingdom after its ruler falls. The ending honours his demonstrated loyalty while redirecting it away from captivity and sacrifice. Because not every branch gives him the same office, this remains a labelled outcome rather than the single canonical ending.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-makaradhwaja-after-rescue', 'hi', 'कुछ कथाएँ मकरध्वज को राज्य सौंपती हैं', 'एक सामान्य बाद के समाधान में शासक के पतन के बाद मकरध्वज को मुक्त कर पाताल-राज्य की जिम्मेदारी दी जाती है। यह अंत उसकी सिद्ध निष्ठा का सम्मान करते हुए उसे बंदीकरण और बलि से दूर दिशा देता है। हर शाखा उसे यही पद नहीं देती, इसलिए यह एक नामित परिणाम है, एकमात्र प्रामाणिक अंत नहीं।'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-return-to-lanka-war', 'en', 'The rescued brothers return to the unfinished war', 'Hanuman brings Rama and Lakshmana back from the hidden world, restoring the leaders the army believed it had lost. The regional adventure now rejoins the familiar Lanka-war horizon. In Devam navigation, the user can return to the selected epic battle without being told that this later detour occurred inside that expression.'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ahiravana-return-to-lanka-war', 'hi', 'बचाए गए दोनों भाई अधूरे युद्ध में लौटते हैं', 'हनुमान राम और लक्ष्मण को गुप्त लोक से वापस लाते हैं और सेना को वे नेता मिल जाते हैं जिन्हें वह खो चुकी समझती थी। क्षेत्रीय साहसिक कथा अब परिचित लंका-युद्ध के क्षितिज से फिर जुड़ती है। देवम् में उपयोगकर्ता चयनित महाकाव्य-युद्ध पर लौट सकता है, बिना यह कहे कि यह बाद की यात्रा उसी पाठ में हुई थी।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-sita-finds-refuge', 'en', 'Sita reaches Valmiki''s refuge', 'After Sita is sent away from Ayodhya while pregnant, Valmiki gives her refuge in his ashram. The popular brief links the exile to public accusation, but that explanation does not make the decision harmless or consensual. The forest becomes the home in which her children will grow without knowing their full connection to Ayodhya.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-sita-finds-refuge', 'hi', 'सीता वाल्मीकि के आश्रम में शरण पाती हैं', 'गर्भवती सीता को अयोध्या से भेजे जाने के बाद वाल्मीकि उन्हें अपने आश्रम में शरण देते हैं। लोकप्रिय संक्षिप्त कथा वनवास को जन-आरोप से जोड़ती है, पर यह कारण निर्णय को अहानिकर या सहमति-आधारित नहीं बनाता। वन वह घर बनता है जहाँ उनके बच्चे अयोध्या से अपना पूरा संबंध जाने बिना बड़े होंगे।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-raised-and-trained', 'en', 'Lava and Kusha grow into skilled students', 'Sita gives birth to twins, Lava and Kusha. Valmiki''s ashram provides education in learning, archery, warfare, and the disciplines expected in the telling of capable princes. Their skill does not arrive suddenly at the horse: it grows through a childhood whose teachers and mother prepare them for a world that has not yet recognized them.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-raised-and-trained', 'hi', 'लव और कुश कुशल शिष्य बनते हैं', 'सीता जुड़वाँ पुत्रों लव और कुश को जन्म देती हैं। वाल्मीकि का आश्रम उन्हें ज्ञान, धनुर्विद्या, युद्ध-कौशल और समर्थ राजकुमारों के लिए अपेक्षित अनुशासन की शिक्षा देता है। अश्व के सामने उनका कौशल अचानक नहीं आता; वह उस बाल्यकाल में बनता है जहाँ गुरु और माता उन्हें ऐसी दुनिया के लिए तैयार करते हैं जिसने अभी उन्हें पहचाना नहीं।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-learn-rama-story', 'en', 'The twins learn to carry Rama''s story', 'Valmiki teaches the twins the Ramayana, and they become its young reciters. They can carry the public story of Rama before the hidden family relationship is resolved. This creates the central tension of their later meeting: they know the king through narrative and reputation, while he does not yet know them as his sons.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-learn-rama-story', 'hi', 'जुड़वाँ राम की कथा को स्वर देना सीखते हैं', 'वाल्मीकि जुड़वाँ भाइयों को रामायण सिखाते हैं और वे उसके युवा गायक बनते हैं। पारिवारिक संबंध खुलने से पहले ही वे राम की सार्वजनिक कथा को स्वर दे सकते हैं। यही उनकी बाद की भेंट का केंद्रीय तनाव बनता है: वे राजा को कथा और कीर्ति से जानते हैं, जबकि राजा उन्हें अभी अपने पुत्रों के रूप में नहीं जानते।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-horse-released', 'en', 'Rama releases the Ashvamedha horse', 'During Rama''s Ashvamedha, a marked horse is released to travel under military protection. In the TTD account, allowing it to pass accepts the sponsoring king''s claim, while stopping it signals readiness to contest that claim. The horse therefore carries political meaning as well as ritual meaning wherever it goes.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-horse-released', 'hi', 'राम अश्वमेध का अश्व छोड़ते हैं', 'राम के अश्वमेध में चिह्नित अश्व को सैनिक सुरक्षा के साथ विचरण के लिए छोड़ा जाता है। टीटीडी की कथा में उसे निर्बाध जाने देना यज्ञकर्ता राजा के दावे को स्वीकारना है, जबकि रोकना उस दावे को चुनौती देना। इसलिए अश्व जहाँ जाता है, वहाँ अनुष्ठानिक अर्थ के साथ राजनीतिक अर्थ भी ले जाता है।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-stop-and-tie-horse', 'en', 'The twins stop and tether the horse', 'Lava and Kusha find the wandering horse, stop it, and tie it near the ashram. What may first look like two children keeping an attractive animal is, under the horse''s inscription and escort, a direct challenge. Their decision forces Ayodhya''s representatives to speak with people they do not recognize before choosing violence.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-stop-and-tie-horse', 'hi', 'जुड़वाँ अश्व को रोककर बाँध देते हैं', 'लव और कुश घूमते अश्व को पाकर रोकते और आश्रम के निकट बाँध देते हैं। जो पहले दो बच्चों द्वारा सुंदर पशु को रोकना लग सकता है, वह अश्व के लेख और सैनिक दल के कारण सीधी चुनौती है। उनका निर्णय अयोध्या के प्रतिनिधियों को हिंसा चुनने से पहले ऐसे लोगों से बात करने को बाध्य करता है जिन्हें वे पहचानते नहीं।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-refuse-soldiers', 'en', 'The first soldiers cannot persuade or defeat them', 'The escort tells the twins that the horse belongs to Rama, conqueror of Lanka, and orders its release. Lava and Kusha refuse. Fighting follows, and the soldiers return to Ayodhya defeated, turning a local encounter into news that the royal court can no longer ignore.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-refuse-soldiers', 'hi', 'पहले सैनिक उन्हें न मना पाते हैं, न हरा पाते हैं', 'सैनिक जुड़वाँ भाइयों को बताते हैं कि अश्व लंका-विजेता राम का है और उसे छोड़ने का आदेश देते हैं। लव और कुश मना कर देते हैं। युद्ध होता है और सैनिक पराजित होकर अयोध्या लौटते हैं; स्थानीय मुठभेड़ अब ऐसा समाचार बन जाती है जिसे राजदरबार अनदेखा नहीं कर सकता।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-shatrughna-falls', 'en', 'Shatrughna leads the next attempt', 'Rama sends Shatrughna with a larger force to recover the horse. The twins meet the escalation with the training they have received and leave Shatrughna unconscious. The result deepens the puzzle: unknown young fighters have now defeated not merely an escort but a prince of Ayodhya.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-shatrughna-falls', 'hi', 'शत्रुघ्न अगला प्रयास लेकर आते हैं', 'राम शत्रुघ्न को बड़ी सेना के साथ अश्व वापस लाने भेजते हैं। जुड़वाँ अपने प्रशिक्षण से इस बढ़े हुए बल का सामना करते हैं और शत्रुघ्न को मूर्छित कर देते हैं। रहस्य गहरा जाता है: अज्ञात बाल योद्धाओं ने केवल सैनिक दल नहीं, अयोध्या के राजकुमार को भी पराजित किया है।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-bharata-lakshmana-fall', 'en', 'Bharata and Lakshmana also fail to bring the horse back', 'The TTD sequence next sends Bharata and Lakshmana with their armies. They too are defeated and rendered unconscious. Each escalation raises the cost while withholding the fact that could stop it: the combatants belong to the same family, but the knowledge is still divided between forest and court.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-bharata-lakshmana-fall', 'hi', 'भरत और लक्ष्मण भी अश्व वापस नहीं ला पाते', 'टीटीडी का क्रम आगे भरत और लक्ष्मण को उनकी सेनाओं के साथ भेजता है। वे भी पराजित होकर मूर्छित होते हैं। हर बढ़ता टकराव कीमत बढ़ाता है, जबकि उसे रोक सकने वाला तथ्य छिपा रहता है: योद्धा एक ही परिवार के हैं, पर यह ज्ञान अभी वन और दरबार के बीच बँटा है।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-rama-arrives', 'en', 'Rama comes to see the young challengers himself', 'Reports of the twins'' courage and refusal finally bring Rama to the forest battlefield. He sees how young they are and is reluctant to fight, but they challenge him to recover the horse. He uses restrained weapons in the account, while their precise answers make him wonder who could have trained them so well.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-rama-arrives', 'hi', 'राम स्वयं युवा चुनौतीकर्ताओं को देखने आते हैं', 'जुड़वाँ भाइयों के साहस और अडिगता की खबर अंततः राम को वन की रणभूमि तक लाती है। उनकी कम आयु देखकर राम लड़ने में संकोच करते हैं, पर वे उन्हें अश्व छुड़ाने की चुनौती देते हैं। कथा में राम संयत अस्त्र चलाते हैं और उनके सटीक प्रत्युत्तर देखकर सोचते हैं कि उन्हें इतना उत्तम प्रशिक्षण किसने दिया।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-hanuman-recognizes-resemblance', 'en', 'Hanuman follows a resemblance back to the ashram', 'Hanuman notices that the boys resemble Rama and Lakshmana in youth. Instead of treating resemblance as proof, he goes to the ashram to find their mother and discovers Sita there. Recognition now becomes an investigation that can reconnect the battlefield to the family history it has been missing.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-hanuman-recognizes-resemblance', 'hi', 'हनुमान समानता का संकेत लेकर आश्रम जाते हैं', 'हनुमान देखते हैं कि बालक युवावस्था के राम और लक्ष्मण जैसे लगते हैं। समानता को प्रमाण मान लेने के बजाय वे उनकी माता को खोजने आश्रम जाते हैं और वहाँ सीता को पाते हैं। अब पहचान एक ऐसी जाँच बनती है जो रणभूमि को उससे छूटे पारिवारिक इतिहास से फिर जोड़ सकती है।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-valmiki-reveals-history', 'en', 'Valmiki and Sita bring the hidden history into the open', 'Valmiki, Sita, and the ashram community come to the field. Valmiki explains what happened after Sita was sent away and identifies Lava and Kusha as Rama''s sons. The revelation stops the conflict by replacing the category of unknown challengers with the relationship that court and children had both been denied.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-valmiki-reveals-history', 'hi', 'वाल्मीकि और सीता छिपे इतिहास को सामने लाते हैं', 'वाल्मीकि, सीता और आश्रम के लोग रणभूमि में आते हैं। वाल्मीकि बताते हैं कि सीता को भेजे जाने के बाद क्या हुआ और लव-कुश को राम के पुत्रों के रूप में पहचानते हैं। यह उद्घाटन ‘अज्ञात चुनौतीकर्ता’ की श्रेणी को उस संबंध से बदलकर युद्ध रोकता है जिससे दरबार और बच्चों दोनों को वंचित रखा गया था।'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-revival-reunion-and-sita-return', 'en', 'Recognition restores the family but does not erase Sita''s ending', 'The twins use what Valmiki taught them to revive those left unconscious, and the TTD brief says the reunited family returns toward Ayodhya. It also places Sita''s return to Mother Earth at this recognition scene. The sons are acknowledged, but the ending does not undo the exile or turn Sita''s departure into evidence that the earlier harm was justified.'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'lava-kusha-revival-reunion-and-sita-return', 'hi', 'पहचान परिवार को जोड़ती है, पर सीता के अंत को नहीं मिटाती', 'जुड़वाँ वाल्मीकि से सीखी विद्या से मूर्छित लोगों को पुनर्जीवित करते हैं और टीटीडी की संक्षिप्त कथा परिवार को अयोध्या की ओर लौटाती है। वही कथा इसी पहचान-दृश्य पर सीता का धरती माता में लौटना भी रखती है। पुत्र स्वीकारे जाते हैं, पर यह अंत वनवास को मिटाता नहीं और न सीता के प्रस्थान को पहले हुए अन्याय का औचित्य बनाता है।'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-coronation-gifts', 'en', 'Ayodhya honours those who made the return possible', 'After Rama''s return and coronation, companions receive gifts and recognition for their service. The public celebration also creates a question especially sharp for Hanuman: what object could equal a relationship he experiences as continuous service? The later devotional tale begins inside that mismatch between royal treasure and inward value.'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-coronation-gifts', 'hi', 'अयोध्या वापसी सम्भव बनाने वालों का सम्मान करती है', 'राम की वापसी और राज्याभिषेक के बाद सहयोगियों को उनकी सेवा के लिए उपहार और सम्मान मिलता है। सार्वजनिक उत्सव हनुमान के लिए एक विशेष प्रश्न भी खड़ा करता है: निरंतर सेवा के रूप में जीए गए संबंध के बराबर कौन-सी वस्तु हो सकती है? बाद की भक्तिपरक कथा राजकीय धन और भीतरी मूल्य के इसी अंतर से आरम्भ होती है।'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-sita-gives-necklace', 'en', 'Sita gives Hanuman a pearl necklace', 'Sita gives Hanuman a precious pearl necklace. A necklace gift is present in the selected expression, but the actions that follow belong to later reception. Hanuman accepts the honour, then studies the pearls rather than simply wearing or displaying them.'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-sita-gives-necklace', 'hi', 'सीता हनुमान को मोतियों की माला देती हैं', 'सीता हनुमान को बहुमूल्य मोतियों की माला देती हैं। माला का उपहार चयनित पाठ में है, पर आगे की घटनाएँ बाद की लोक-स्वीकृति की हैं। हनुमान सम्मान स्वीकारते हैं, फिर उसे केवल पहनने या दिखाने के बजाय मोतियों को ध्यान से जाँचते हैं।'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-searches-pearls', 'en', 'He searches each pearl for Rama', 'Hanuman turns the pearls, listens to or inspects them, and begins opening them one by one. Courtiers see a valuable gift being destroyed; Hanuman sees objects being tested for the only value that matters to him. He says that a pearl without Rama has no use in his service.'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-searches-pearls', 'hi', 'वे हर मोती में राम को खोजते हैं', 'हनुमान मोतियों को घुमाकर, सुनकर अथवा देखकर एक-एक कर खोलने लगते हैं। दरबारियों को बहुमूल्य उपहार नष्ट होता दिखता है; हनुमान उन वस्तुओं को उस एक मूल्य पर परख रहे हैं जो उनके लिए आवश्यक है। वे कहते हैं कि जिसमें राम नहीं, वह मोती उनकी सेवा में उपयोगी नहीं।'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-court-challenges-him', 'en', 'The court turns his test back on him', 'Someone in the assembly asks whether Hanuman''s own body contains Rama; if not, by his rule it too would be worthless. The challenge exposes the difference between a slogan and a claim he is prepared to embody. Hanuman does not retreat into explanation.'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-court-challenges-him', 'hi', 'दरबार वही कसौटी हनुमान पर रखता है', 'सभा में कोई पूछता है कि क्या हनुमान के अपने शरीर में राम हैं; यदि नहीं, तो उनकी कसौटी से शरीर भी व्यर्थ होगा। यह चुनौती नारे और उस दावे का अंतर सामने लाती है जिसे वे स्वयं जीने को तैयार हैं। हनुमान केवल शब्दों की सफाई में पीछे नहीं हटते।'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-opens-heart', 'en', 'Hanuman opens his chest', 'In the devotional miracle, Hanuman opens his chest. Rama and Sita are revealed enthroned within his heart, and some versions extend Rama''s name through his whole body. The image makes inward devotion visible; it is not anatomy, self-harm guidance, or an event attributed here to the selected epic.'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-opens-heart', 'hi', 'हनुमान अपना वक्ष खोलते हैं', 'भक्तिपरक चमत्कार में हनुमान अपना वक्ष खोलते हैं। उनके हृदय में राम और सीता विराजमान दिखाई देते हैं और कुछ रूप पूरे शरीर में राम-नाम दिखाते हैं। यह छवि अंतःकरण की भक्ति को दृश्य बनाती है; यह शरीर-विज्ञान, आत्म-हानि का निर्देश या चयनित महाकाव्य की घटना नहीं।'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-rama-embraces', 'en', 'Rama heals and embraces his devotee', 'The assembly''s doubt turns to wonder. Rama rises, embraces Hanuman, and in the tale restores his chest. The answer to the challenge is not that pearls or bodies are inherently worthless, but that Hanuman measures his own identity through remembered relationship and service.'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-rama-embraces', 'hi', 'राम अपने भक्त को स्वस्थ कर गले लगाते हैं', 'सभा का संशय विस्मय में बदल जाता है। कथा में राम उठकर हनुमान को गले लगाते और उनका वक्ष पुनः स्वस्थ कर देते हैं। चुनौती का उत्तर यह नहीं कि मोती या शरीर अपने आप में व्यर्थ हैं, बल्कि यह कि हनुमान अपनी पहचान को स्मरण, संबंध और सेवा से मापते हैं।'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-returns-to-living-image', 'en', 'The story continues through devotional art', 'The open-chest Hanuman becomes a widely recognizable visual statement of Rama-bhakti. A user may move from this story to Hanuman''s wider devotional world or the complete Hanuman Chalisa reading, but the image does not replace either text. Its role is to make one later devotional understanding memorable and navigable.'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'hanuman-chest-returns-to-living-image', 'hi', 'कथा भक्तिपरक चित्रकला में आगे जीवित रहती है', 'खुले हृदय वाले हनुमान राम-भक्ति का व्यापक रूप से पहचाना जाने वाला दृश्य-चिह्न बनते हैं। उपयोगकर्ता यहाँ से हनुमान की व्यापक भक्तिपरक दुनिया या संपूर्ण हनुमान चालीसा पाठ तक जा सकता है, पर छवि किसी पाठ का स्थान नहीं लेती। उसका काम एक बाद की भक्ति-समझ को स्मरणीय और अन्वेषण योग्य बनाना है।'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-palace-service', 'en', 'Hanuman wants every part of life to become service', 'The popular story places Hanuman in Rama''s palace, always eager to remain close and useful. Some versions begin when the royal couple enters private space and Hanuman wonders why Sita may accompany Rama where he cannot. That prelude is optional across tellings, but it establishes his literal, searching devotion rather than entitlement to their privacy.'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-palace-service', 'hi', 'हनुमान जीवन के हर भाग को सेवा बनाना चाहते हैं', 'लोकप्रिय कथा हनुमान को राम के महल में रखती है, जहाँ वे सदा निकट रहकर सेवा करना चाहते हैं। कुछ रूप तब आरम्भ होते हैं जब राजदंपती निजी कक्ष में जाते हैं और हनुमान सोचते हैं कि सीता वहाँ जा सकती हैं, वे क्यों नहीं। यह भूमिका सभी कथाओं में नहीं, पर उनकी सीधी, जिज्ञासु भक्ति दिखाती है, निजी स्थान पर अधिकार नहीं।'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-sees-sita', 'en', 'He sees Sita applying sindoor', 'Hanuman sees Sita place sindoor in the parting of her hair and asks why she does it. Within the social world of the tale, it is an auspicious sign associated with a married woman. Devam reports that context without turning it into a requirement for every woman, marriage, region, or household.'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-sees-sita', 'hi', 'वे सीता को सिंदूर लगाते देखते हैं', 'हनुमान सीता को माँग में सिंदूर लगाते देखकर उसका कारण पूछते हैं। कथा के सामाजिक संसार में यह विवाहित स्त्री से जुड़ा मंगल-चिह्न है। देवम् इस संदर्भ को बताता है, पर इसे हर स्त्री, विवाह, क्षेत्र या परिवार के लिए अनिवार्य नियम नहीं बनाता।'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-hears-popular-meaning', 'en', 'Sita gives the answer remembered in the tale', 'Sita answers, in the familiar story, that she wears it for Rama''s long life or wellbeing. The statement expresses the belief inside the modern devotional tale; it is not medical causation or a promise that a cosmetic determines another person''s lifespan. Hanuman receives it with the wholehearted literalness that drives the next turn.'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-hears-popular-meaning', 'hi', 'सीता कथा में स्मरण किया गया उत्तर देती हैं', 'परिचित कथा में सीता उत्तर देती हैं कि वे इसे राम की दीर्घायु अथवा कुशलता के लिए लगाती हैं। यह कथानक के भीतर की मान्यता है; यह चिकित्सकीय कारण या यह वादा नहीं कि प्रसाधन किसी की आयु निर्धारित करता है। हनुमान इसे अपने पूर्ण और सीधेसादे समर्पण के साथ सुनते हैं, जिससे अगला मोड़ बनता है।'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-reasons-with-devotion', 'en', 'A small mark becomes, in his mind, a whole-body offering', 'Hanuman reasons that if a small amount expresses care for Rama, covering every hair of his body would express even more. The logic is deliberately comic and devotional rather than ritual jurisprudence. It reveals a character who does not calculate a minimum offering when he believes Rama may benefit.'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-reasons-with-devotion', 'hi', 'उनके मन में छोटा चिह्न पूरे शरीर का अर्पण बन जाता है', 'हनुमान सोचते हैं कि यदि थोड़ा-सा सिंदूर राम के लिए मंगल की कामना व्यक्त करता है, तो शरीर के हर रोम को ढकना उससे भी अधिक समर्पण होगा। यह तर्क जानबूझकर हास्यपूर्ण और भक्तिपरक है, अनुष्ठान-विधि नहीं। यह ऐसे चरित्र को दिखाता है जो राम के हित की कल्पना करते समय न्यूनतम अर्पण की गणना नहीं करता।'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-covers-body', 'en', 'Hanuman returns completely red-orange', 'He covers himself in sindoor and returns to Rama''s court from head to tail in radiant red-orange. The assembly reacts with surprise and laughter because a familiar marital mark has been expanded beyond ordinary scale. Sita understands the question that produced the spectacle, while Rama asks Hanuman to explain himself.'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-covers-body', 'hi', 'हनुमान पूरे लाल-नारंगी होकर लौटते हैं', 'वे स्वयं को सिंदूर से ढककर सिर से पूँछ तक चमकते लाल-नारंगी रूप में राम के दरबार लौटते हैं। सभा आश्चर्य और हँसी से प्रतिक्रिया करती है, क्योंकि परिचित वैवाहिक चिह्न सामान्य सीमा से बहुत आगे बढ़ गया है। सीता उस प्रश्न को समझती हैं जिससे यह दृश्य बना और राम हनुमान से कारण पूछते हैं।'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-rama-embraces', 'en', 'Rama recognizes the intention beneath the spectacle', 'Hanuman says that he wants Rama''s life and wellbeing multiplied by every hair he has covered. Rama responds to the intention with affection and embraces him. The devotional resolution values love expressed without self-interest; it does not establish that using more material produces more spiritual or worldly reward.'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-rama-embraces', 'hi', 'राम दृश्य के पीछे का भाव पहचानते हैं', 'हनुमान कहते हैं कि वे अपने ढके हुए हर रोम के बराबर राम की आयु और कुशलता की कामना करते हैं। राम उस भाव को प्रेम से स्वीकारकर उन्हें गले लगाते हैं। भक्तिपरक समाधान निष्काम प्रेम को महत्त्व देता है; यह नियम नहीं बनाता कि अधिक सामग्री से अधिक आध्यात्मिक या सांसारिक फल मिलेगा।'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-story-and-practice-separated', 'en', 'The later story explains a practice without governing it', 'Scholarly reception history notes no known premodern textual source for this story and sees it as a modern explanation for Hanuman''s widespread sindoor association. Some versions append Tuesday offerings and promised wish fulfilment; Devam labels those as variant phalashruti, not guarantees. Actual temple handling, permitted materials, days, and who may apply them belong to each institution''s current rules, not this story.'),
  ('ramayana-popular-hanuman-sindoor-v1', 'hanuman-sindoor-story-and-practice-separated', 'hi', 'बाद की कथा प्रथा का अर्थ बताती है, उसे सार्वभौमिक रूप से नियंत्रित नहीं करती', 'लोक-स्वीकृति के विद्वत इतिहास में इस कथा का कोई ज्ञात पूर्व-आधुनिक पाठ-स्रोत नहीं मिलता और इसे हनुमान से सिंदूर के व्यापक संबंध की आधुनिक व्याख्या माना गया है। कुछ रूप मंगलवार के अर्पण और मनोकामना-पूर्ति का फल जोड़ते हैं; देवम् उन्हें कथा-विशेष का फलश्रुति-वचन कहता है, गारंटी नहीं। मंदिर में सामग्री, दिन और लगाने की अनुमति प्रत्येक संस्था के वर्तमान नियमों से तय होगी, इस कथा से नहीं।')
) as source(moment_slug, beat_slug, language_code, title, narration)
join public.narrative_series series on series.slug='ramayana-expected-stories-later-devotional-v1'
join public.narrative_moments moment on moment.series_id=series.id and moment.slug=source.moment_slug
join public.narrative_beats beat on beat.moment_id=moment.id and beat.slug=source.beat_slug
on conflict (beat_id, language_code) do update set title=excluded.title, narration=excluded.narration, text_status=excluded.text_status,
  rights_lane=excluded.rights_lane, publication_state=excluded.publication_state, updated_at=now();

insert into public.narrative_moment_links (source_moment_id, target_moment_id, link_kind, label)
select source_moment.id, target_moment.id, source.link_kind, 'curated later-reception traversal'
from (values
  ('ramayana-popular-sulochana-meghnad-v1', 'ramayana-regional-ahiravana-mahiravana-rescue-v1', 'precedes'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ramayana-popular-sulochana-meghnad-v1', 'follows'),
  ('ramayana-regional-ahiravana-mahiravana-rescue-v1', 'ramayana-popular-lava-kusha-ashvamedha-v1', 'precedes'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'ramayana-regional-ahiravana-mahiravana-rescue-v1', 'follows'),
  ('ramayana-popular-lava-kusha-ashvamedha-v1', 'ramayana-popular-hanuman-opens-chest-v1', 'precedes'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'ramayana-popular-lava-kusha-ashvamedha-v1', 'follows'),
  ('ramayana-popular-hanuman-opens-chest-v1', 'ramayana-popular-hanuman-sindoor-v1', 'precedes'),
  ('ramayana-popular-hanuman-sindoor-v1', 'ramayana-popular-hanuman-opens-chest-v1', 'follows')
) as source(source_slug, target_slug, link_kind)
join public.narrative_series series on series.slug='ramayana-expected-stories-later-devotional-v1'
join public.narrative_moments source_moment on source_moment.series_id=series.id and source_moment.slug=source.source_slug
join public.narrative_moments target_moment on target_moment.series_id=series.id and target_moment.slug=source.target_slug
on conflict (source_moment_id, target_moment_id, link_kind) do update set label=excluded.label;

do $devam$
declare story_count integer; beat_count integer; bilingual_story_text_count integer; bilingual_beat_text_count integer;
begin
  select count(*) into story_count from public.narrative_moments moment join public.narrative_series series on series.id=moment.series_id
  where series.slug='ramayana-expected-stories-later-devotional-v1' and moment.source_range->>'snapshotContract'='DEVAM_RAMAYANA_EXPECTED_STORIES_LATER_DEVOTIONAL_DB_V1';
  select count(*) into beat_count from public.narrative_beats beat join public.narrative_moments moment on moment.id=beat.moment_id
  join public.narrative_series series on series.id=moment.series_id where series.slug='ramayana-expected-stories-later-devotional-v1';
  select count(*) into bilingual_story_text_count from public.narrative_moment_texts text join public.narrative_moments moment on moment.id=text.moment_id
  join public.narrative_series series on series.id=moment.series_id where series.slug='ramayana-expected-stories-later-devotional-v1';
  select count(*) into bilingual_beat_text_count from public.narrative_beat_texts text join public.narrative_beats beat on beat.id=text.beat_id
  join public.narrative_moments moment on moment.id=beat.moment_id join public.narrative_series series on series.id=moment.series_id
  where series.slug='ramayana-expected-stories-later-devotional-v1';
  if story_count <> 5 then raise exception 'Expected 5 later and devotional Ramayana stories, got %', story_count; end if;
  if beat_count <> 45 then raise exception 'Expected 45 later and devotional Ramayana story beats, got %', beat_count; end if;
  if bilingual_story_text_count <> 10 then raise exception 'Expected 10 bilingual story texts, got %', bilingual_story_text_count; end if;
  if bilingual_beat_text_count <> 90 then raise exception 'Expected 90 bilingual beat texts, got %', bilingual_beat_text_count; end if;
end
$devam$;

commit;
